import "server-only";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { eq } from "drizzle-orm";
import { db } from "@/db/client";
import { blobs as blobTable } from "@/db/schema";
import { env } from "@/lib/env";

/**
 * File storage behind one small interface. Development writes to local disk;
 * production keeps files in Postgres, shared by the web app and the worker on
 * their separate hosts (object storage can replace it without touching
 * callers). Keys are generated by us, never taken from user input.
 */
export interface BlobStore {
  put(key: string, data: Uint8Array): Promise<void>;
  get(key: string): Promise<Uint8Array>;
}

const SAFE_KEY = /^[a-z0-9][a-z0-9/_.-]{0,300}$/;

function localStore(root: string): BlobStore {
  const resolve = (key: string) => {
    if (!SAFE_KEY.test(key) || key.includes("..")) throw new Error(`Unsafe storage key: ${key}`);
    return path.join(root, key);
  };
  return {
    async put(key, data) {
      const file = resolve(key);
      await mkdir(path.dirname(file), { recursive: true });
      await writeFile(file, data);
    },
    async get(key) {
      return new Uint8Array(await readFile(resolve(key)));
    },
  };
}

const safe = (key: string) => {
  if (!SAFE_KEY.test(key) || key.includes("..")) throw new Error(`Unsafe storage key: ${key}`);
  return key;
};

function databaseStore(): BlobStore {
  return {
    async put(key, data) {
      await db()
        .insert(blobTable)
        .values({ key: safe(key), data, size: data.byteLength })
        .onConflictDoUpdate({ target: blobTable.key, set: { data, size: data.byteLength } });
    },
    async get(key) {
      const [row] = await db()
        .select({ data: blobTable.data })
        .from(blobTable)
        .where(eq(blobTable.key, safe(key)));
      if (!row) throw new Error(`No such file: ${key}`);
      return row.data;
    },
  };
}

let store: BlobStore | undefined;
export function blobs(): BlobStore {
  const driver = env().STORAGE_DRIVER ?? (env().NODE_ENV === "production" ? "database" : "disk");
  store ??= driver === "database" ? databaseStore() : localStore(path.resolve(env().STORAGE_DIR));
  return store;
}
